import { DashboardLink, FormLink, SSLinkProp, NavigationRoute } from "../types";

export enum ActionType {
    SetFetchingData = "SET_FETCHING_DATA",
    SetShowFullMenu = "SET_SHOW_FULL_MENU",
    SetCurrentPage = "SET_CURRENT_PAGE",
    SetUserNavLinks = "SET_NAV_LINKS",
    SetUserLinks = "SET_USER_LINKS",
    SetConfigLink = "SET_CONFIG_LINK",
    SetActivePage = "SET_ACTIVE_PAGE",
    SetDashboardLinks = "SET_DASHBOARD_LINKS",
    SetDashboardProps = "SET_DASHBOARD_PROPS",
}

interface ISetFetchingData {
    type: ActionType.SetFetchingData;
    payload: boolean;
}

interface ISetShowFullMenu {
    type: ActionType.SetShowFullMenu;
    payload: boolean;
}

interface ISetCurrentPage {
    type: ActionType.SetCurrentPage;
    payload: any;
}

interface IsetUserNavLinks {
    type: ActionType.SetUserNavLinks;
    payload: NavigationRoute[];
}

interface IFormLinks {
    type: ActionType.SetUserLinks;
    payload: FormLink[];
}

interface ISetConfigLink {
    type: ActionType.SetConfigLink;
    payload: string;
}

interface ISetActivePage {
    type: ActionType.SetActivePage;
    payload: string;
}

interface ISetDashboardLinks {
    type: ActionType.SetDashboardLinks;
    payload: DashboardLink[];
}

interface ISetDashboardProps {
    type: ActionType.SetDashboardProps;
    payload: SSLinkProp;
}

export type Actions =
    | ISetFetchingData
    | ISetShowFullMenu
    | ISetCurrentPage
    | IsetUserNavLinks
    | IFormLinks
    | ISetConfigLink
    | ISetActivePage
    | ISetDashboardLinks
    | ISetDashboardProps;

export const setFetchingData = (response: boolean): ISetFetchingData => ({
    type: ActionType.SetFetchingData,
    payload: response,
});

export const setShowFullMenu = (response: boolean): ISetShowFullMenu => ({
    type: ActionType.SetShowFullMenu,
    payload: response,
});

export const setCurrentPage = (response: any): ISetCurrentPage => ({
    type: ActionType.SetCurrentPage,
    payload: response,
});

export const setUserNavLinks = (
    response: NavigationRoute[]
): IsetUserNavLinks => ({
    type: ActionType.SetUserNavLinks,
    payload: response,
});

export const setFormLinks = (response: FormLink[]): IFormLinks => ({
    type: ActionType.SetUserLinks,
    payload: response,
});

export const setActivePage = (response: string): ISetActivePage => ({
    type: ActionType.SetActivePage,
    payload: response,
});

export const setDashboardLinks = (
    response: DashboardLink[]
): ISetDashboardLinks => ({
    type: ActionType.SetDashboardLinks,
    payload: response,
});

export const setDashboardProps = (
    response: SSLinkProp
): ISetDashboardProps => ({
    type: ActionType.SetDashboardProps,
    payload: response,
});
