import { Asset } from ".";

export type NavigationRoute = {
    link?: string;
    label: string;
    icon: Asset;
    id: string;
    enabled?: boolean;
    external?: boolean;
    subLinks?: NavigationRoute[];
    active?: boolean;
};

export type DataLink = {
    Url: string;
    Text: string;
    Name: string;
    Icon: Asset;
    PageId: string;
    Enabled: boolean;
    External: boolean;
    Show?: boolean;
};

export type SSWidget = {
    Name: string;
    Label: string;
    Enabled: boolean;
};

export interface SSLink extends DataLink {
    Menu: DataLink[];
}

export interface DashboardLink {
    Id: string;
    Link: SSLink;
    Name: string;
    Rank: number;
    Widgets: SSWidget[];
    ShowName?: boolean;
    isNew?: boolean;
}

export interface FormLink extends DataLink {
    TemplateId: string;
    WorkflowDefinitionId: string;
}

export const EMPTY_LINK = {
    Url: "",
    Name: "",
    Text: "",
    Icon: "",
    PageId: "0",
    Enabled: false,
    External: false,
    Show: true,
};

export const EMPTY_APPLICATION: DashboardLink = {
    Id: "",
    Link: {
        ...EMPTY_LINK,
        Menu: [],
    },
    Name: "New App",
    Rank: 0,
    Widgets: [],
    ShowName: true,
    isNew: true,
};

export interface DBForm {
    Apps: DashboardLink[];
    Forms?: FormLink[];
    Id?: string;
    Url?: string;
    Enabled: boolean;
}
